// ── Collect every WordPress site that has a Jetpack Site ID configured ──
// Requires Jetpack active + connected to WordPress.com on that site (see the
// hint in the Whizz Integrations page for how to find the numeric ID).
// Always emits exactly one item — an empty "sites" array is a valid, expected
// result (nothing configured yet), not an error.
//
// "period" comes from the Whizz Reports page's month selector: "all" (default —
// last 7 days) or "YYYY-MM" (that whole calendar month, one bucket per day).
// Jetpack's stats/visits endpoint takes unit + quantity + an anchor "date".
const query = $('Webhook').first().json.query || {};
const period = query.period;

let unit = 'day', quantity = '7', date = new Date().toISOString().slice(0, 10);
if (period && period !== 'all') {
  const [y, m] = period.split('-').map(Number);
  const lastDay = new Date(y, m, 0);
  unit = 'day';
  quantity = String(lastDay.getDate());
  date = `${y}-${String(m).padStart(2, '0')}-${String(lastDay.getDate()).padStart(2, '0')}`;
}

const rows = $input.all();
const sites = rows
  .filter(r => (r.json.service || '').toLowerCase().startsWith('wordpress:'))
  .map(r => { try { return JSON.parse(r.json.data || '{}'); } catch (e) { return null; } })
  .filter(d => d && d.jetpackSiteId)
  .map(d => ({ id: d.id, label: d.label || d.siteUrl, jetpackSiteId: d.jetpackSiteId, unit, quantity, date }));

return [{ json: { hasSites: sites.length > 0, sites } }];

// Fan the single "sites" list out into one n8n item per site, so the HTTP
// Request node below runs once per site automatically.
const item = $input.first().json;
return (item.sites || []).map(s => ({ json: s }));

// ── Normalize each site's Jetpack "visits" response into a simple summary ──
// "Split Sites" -> "Fetch Jetpack Stats" is a straight, unfiltered chain, so
// item order/count lines up 1:1 — we zip the two lists by index to recover
// each response's site id/label (the HTTP Request node replaces $json with
// the raw API response, so the site metadata has to be looked up this way).
const sitesMeta = $('Split Sites').all();
const responses = $input.all();

const sites = sitesMeta.map((metaItem, i) => {
  const meta = metaItem.json;
  const resp = (responses[i] && responses[i].json) || {};
  const fields = resp.fields || [];
  const rows = resp.data || [];
  const viewsIdx = fields.indexOf('views');
  const visitorsIdx = fields.indexOf('visitors');
  const periodIdx = fields.indexOf('period');

  const daily = rows.map(r => ({
    date: periodIdx >= 0 ? r[periodIdx] : null,
    views: viewsIdx >= 0 ? (r[viewsIdx] || 0) : 0,
    visitors: visitorsIdx >= 0 ? (r[visitorsIdx] || 0) : 0
  }));

  return {
    id: meta.id,
    label: meta.label,
    views: daily.reduce((sum, d) => sum + d.views, 0),
    visitors: daily.reduce((sum, d) => sum + d.visitors, 0),
    daily,
    error: resp.error ? (resp.message || resp.error) : null
  };
});

return [{ json: { sites } }];
